public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers");
    }

    int count = 0;
    int year = Y;

    while (count < N) {
        year++;
        if (isLeapYear(year)) {
            count++;
        }
    }

    return year;
}

