public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }

    int count = 0;
    for (int i = 0; i < numbers.length; i++) {
        for (int j = 0; j < numbers.length; j++) {
            if (i != j && numbers[i] == 2 * numbers[j]) {
                count++;
                break;
            }
        }
    }
    return count;
}

