public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        throw new IllegalArgumentException("Date string cannot be null or empty");
    }

    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Date must be in format 'MM dd yyyy'");
    }

    int month, day, year;
    try {
        month = Integer.parseInt(parts[0]);
        day = Integer.parseInt(parts[1]);
        year = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Invalid date format: " + e.getMessage());
    }

    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Month must be between 1 and 12");
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Day must be between 1 and 31");
    }
    if (year < 1) {
        throw new IllegalArgumentException("Year must be positive");
    }

    // Validate the date using Calendar
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.clear();
    cal.set(year, month - 1, day);

    if (!cal.isSet(java.util.Calendar.DAY_OF_MONTH)) {
        throw new IllegalArgumentException("Invalid date");
    }

    // Check if the date is valid
    int actualDay = cal.get(java.util.Calendar.DAY_OF_MONTH);
    if (actualDay != day) {
        throw new IllegalArgumentException("Invalid date: day out of range for the given month and year");
    }

    String[] monthNames = {"January", "February", "March", "April", "May", "June",
                           "July", "August", "September", "October", "November", "December"};
    String[] weekdayNames = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    int weekdayIndex = cal.get(java.util.Calendar.DAY_OF_WEEK) - 1;
    String weekday = weekdayNames[weekdayIndex];
