public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }

    int n = arr.length;
    int trimCount = (int) (n * 0.05);

    // Sort the array
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);

    // Sum the elements from trimCount to n - trimCount - 1
    long sum = 0;
    int start = trimCount;
    int end = n - trimCount;
    for (int i = start; i < end; i++) {
        sum += sorted[i];
    }

    int count = end - start;
    if (count == 0) {
        return 0.0;
    }

    return (double) sum / count;
}

