public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];

    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        remainderCount[remainder]++;
    }

    // Check remainder 0: must be even
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // Check pairs of remainders r and k-r
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            // This happens when k is even and r = k/2
            if (remainderCount[r] % 2 != 0) {
                return false;
            }
        } else {
            if (remainderCount[r] != remainderCount[k - r]) {
                return false;
            }
        }
    }

    return true;
}

