public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for i in [0, n-1]
    // The target value to make all elements equal is the average of the array.
    // Sum of arr = sum_{i=0}^{n-1} (2*i + 1) = 2 * (n-1)*n/2 + n = n*(n-1) + n = n^2
    // Average = n^2 / n = n
    // So we need to make all elements equal to n.
    // The number of operations is the sum of positive differences (or negative differences) from the target.
    // Since the array is symmetric around the average, we can compute the sum of (n - arr[i]) for i where arr[i] < n.
    // arr[i] = 2*i + 1 < n  =>  2*i + 1 < n  =>  i < (n-1)/2
    // For each such i, the difference is n - (2*i + 1) = n - 2*i - 1.
    // We sum these differences for i from 0 to floor((n-1)/2) - 1? Let's check.

    // Actually, let's just compute the sum of absolute differences from the target, divided by 2? No.
    // Each operation moves 1 unit from one element to another. So the total number of operations is the sum of all positive differences (which equals the sum of all negative differences in absolute value).
    // So we can compute: sum_{i=0}^{n-1} max(0, n - (2*i + 1))

    int target = n;
    int operations = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val < target) {
            operations += target - val;
        }
    }
    return operations;
}

