public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }

    int ones = 0;
    int twos = 0;

    for (int num : nums) {
        // Update twos: set bits that are in both ones and num
        twos |= (ones & num);
        // Update ones: toggle bits that are in num but not already in twos
        ones ^= num;
        // Common bits in ones and twos are the bits that have appeared 3 times, reset them
        int threes = ones & twos;
        // Remove the bits that have appeared 3 times from both ones and twos
        ones &= ~threes;
        twos &= ~threes;
    }

    return ones;
}

