    int maxLen = 0;

    // dp[i][j][0] = horizontal, dp[i][j][1] = vertical, dp[i][j][2] = diagonal, dp[i][j][3] = anti-diagonal
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
